import { preparationMinutes } from './preparation-model.js';
import { getCloud } from './cloud-client.js';
import { createTablePDF } from './pdf-report.js';
import { canonicalCode, splitContainers, groupLots, groupByProvider, monthlyMovementDetails } from './inventory-model.js';
const paths={box:'M3 7l9-4 9 4-9 4-9-4zm0 0v10l9 4 9-4V7M12 11v10',arrows:'M4 7h14m-4-4 4 4-4 4M20 17H6m4-4-4 4 4 4',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',file:'M14 2H6a2 2 0 0 0-2 2v16h16V8zm0 0v6h6M8 12h8M8 16h6',calendar:'M4 5h16v16H4zM8 2v6M16 2v6M4 10h16M8 14h2M14 14h2',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14M5 12h14',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',chevron:'m9 5 7 7-7 7',warning:'M12 3 2 21h20L12 3zm0 6v5m0 3v1',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',money:'M3 5h18v14H3zM16 12h2M6 12h2M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0',check:'m5 12 4 4L19 6',info:'M12 11v6m0-10v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',x:'m6 6 12 12M6 18 18 6',filter:'M4 6h16M7 12h10M10 18h4',tool:'m14 6 4-4 4 4-4 4-4-4-8 8-4 4 4 4 4-4 4-8'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.box).split('~').map(p=>`<path d="${p}"/>`).join('')}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number(v).toLocaleString('es-MX',{maximumFractionDigits:2});
const money=v=>Number(v).toLocaleString('es-MX',{style:'currency',currency:'MXN'});
const displayDate=v=>new Date(v+'T12:00:00').toLocaleDateString('es-MX',{day:'2-digit',month:'short',year:'numeric'}).replaceAll('.','');
const monthLabel=v=>new Date(v+'-02T12:00:00').toLocaleDateString('es-MX',{month:'long',year:'numeric'});
let readOnly=false,cloud=null;
let data,view='inventario',tab='tinta',query='',typeFilter='',providerFilter='',statusFilter='',page=1,month='',catalogTab='tinta',movementTab='all';
const perPage=10,modal=document.querySelector('#modal'),main=document.querySelector('#main');
let toastTimer;
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3500)}
async function load(){
  cloud=await getCloud();
  if(cloud){
   if(!cloud.hasSession()){renderLogin();return;}
   try{data=await cloud.state();readOnly=false;month ||= data.today.slice(0,7);document.querySelector('#today-label').textContent=displayDate(data.today);document.querySelector('.live').innerHTML='<i></i> Base de datos conectada';render();installLogout();return;}
   catch(error){renderLogin(error.message);return;}
  }
  const r=await fetch('/api/state');
  if(r.ok && (r.headers.get('content-type')||'').includes('application/json')) {
    data=await r.json();readOnly=false;
  } else {
    const preview=await fetch('/preview-data.json');
    if(!preview.ok)throw Error('No se pudo cargar el inventario.');
    const seed=await preview.json();
    const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Mexico_City',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
    const catalogResponse=await fetch('/catalog.json');
    if(!catalogResponse.ok)throw Error('No se pudo cargar el catálogo.');
    const catalog=await catalogResponse.json();
    const products=catalog.map((p,index)=>({...p,id:index+1})),lots=[];
    seed.forEach((row,index)=>{
      let p=products.find(p=>p.code===canonicalCode(row.code));
      if(!p){p={id:products.length+1,code:row.code,name:row.name,kind:row.kind,provider:row.provider,category:'tinta',minimum:1000};products.push(p)}
      lots.push({...row,...p,id:index+1,product_id:p.id,grams:row.grams,cost_kg:row.cost_kg,shelf_days:row.shelf_days});
    });
    data={today,baseline:today,products,lots,orders:[],cuts:[],movements:lots.map(l=>({id:l.id,lot_id:l.id,name:l.name,code:l.code,lot:l.lot,type:'initial',grams:l.grams,cost_kg:l.cost_kg,date:today,reason:'Vista previa · inventario PDF',order_id:null}))};
    readOnly=true;
  }
  month ||= data.today.slice(0,7);
  document.querySelector('#today-label').textContent=new Date(data.today+'T12:00:00').toLocaleDateString('es-MX',{day:'numeric',month:'long',year:'numeric'});
  document.querySelector('.live').innerHTML='<i></i> '+(readOnly?'Vista previa':'Sistema activo');
  render();
}
async function post(route,body){if(cloud){await cloud.action(route,body);await load();return;}if(readOnly)throw Error('Esta es una vista previa. Falta conectar la base de datos para guardar cambios.');const r=await fetch('/api/'+route,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||'No se pudo guardar.');await load()}
function installLogout(){
 let button=document.querySelector('#logout');
 if(!button){button=document.createElement('button');button.id='logout';button.className='btn';button.textContent='Cerrar sesión';document.querySelector('.topbar-right').append(button);}
 button.onclick=async()=>{await cloud.signOut();data=null;button.remove();renderLogin();};
}
function renderLogin(message=''){
 data=null;document.querySelector('#navigation').innerHTML='';document.querySelector('#breadcrumb').textContent='Acceso al inventario';
 document.querySelector('.live').innerHTML='<i></i> Acceso protegido';
 main.innerHTML=`<section class="login-panel"><div class="eyebrow">CONTROL DE PLANTA</div><h1>Tu inventario, conectado.</h1><p class="subtitle">Inicia sesión con tu cuenta autorizada para registrar ingresos, consumos y producción en línea.</p><form id="login-form"><label class="field">Correo electrónico<input name="email" type="email" autocomplete="username" required></label><label class="field">Contraseña<input name="password" type="password" autocomplete="current-password" required></label><p id="login-error" class="form-error" role="alert">${esc(message)}</p><button class="btn primary" type="submit">Entrar al inventario</button></form><p class="form-hint">Solo las cuentas autorizadas por el administrador pueden acceder. Si es la primera configuración, ejecuta setup.sql y autoriza tu usuario en Supabase.</p></section>`;
 document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button'),fields=new FormData(e.target);button.disabled=true;try{await cloud.signIn(fields.get('email'),fields.get('password'));e.target.reset();await load();}catch(error){document.querySelector('#login-error').textContent=error.message;button.disabled=false;}};
 if(cloud.hasSession())installLogout();
}
const navs=[['inventario','box','Inventario'],['movimientos','arrows','Ingresos y egresos'],['catalogo','grid','Catálogo'],['ordenes','file','Órdenes de producción'],['preparacion','clock','Tiempos de preparación'],['cortes','calendar','Cortes mensuales']];
function go(v){view=navs.some(n=>n[0]===v)?v:'inventario';query='';typeFilter='';providerFilter='';statusFilter='';page=1;document.querySelector('.sidebar').classList.remove('open');render()}
window.addEventListener('hashchange',()=>go(location.hash.slice(1)));
document.querySelector('.mobile-menu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');
function days(l){return Math.ceil((Date.parse(l.entry_date)+l.shelf_days*86400000-Date.parse(data.today))/86400000)}
function status(l){if(l.grams<0)return ['warning','Revisar saldo'];if(l.category==='herramental')return l.grams>0?['','Disponible']:['neutral','Sin existencia'];const d=days(l);return d<0?['expired','Vencida']:d<=30?['warning','Por vencer']:['','Vigente']}
function badge(l){const [c,t]=status(l);return `<span class="status ${c}">${t}</span>`}
function swatch(name){const n=name.toLowerCase();if(/amarillo/.test(n))return '#efcc3e';if(/magenta|rodamina/.test(n))return '#d24989';if(/naranja/.test(n))return '#e99844';if(/cian|cyan|azul/.test(n))return /reflex/.test(n)?'#4b609a':'#4da7c4';if(/green|verde/.test(n))return '#67a887';if(/violeta|purpura/.test(n))return '#9672ad';if(/rojo|red|rubi/.test(n))return '#d67a76';if(/negro/.test(n))return '#444b51';if(/beige/.test(n))return '#d4bd95';if(/blanco/.test(n))return '#f0eee6';return '#bac7bb'}
function ink(l){return `<div class="ink-cell"><span class="swatch" style="background:${swatch(l.name)}"></span><span><span class="ink-name">${esc(l.name)}</span><span class="ink-code">${esc(l.code)}</span></span></div>`}
function button(text,action,ic='plus',primary=false,extra=''){return `<button class="btn ${primary?'primary':''}" data-action="${action}" ${extra}>${icon(ic)}${text}</button>`}
function header(eyebrow,title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`}
function stat(label,value,unit,note,ic='box',color=''){return `<div class="stat ${color}"><div class="stat-top">${label}<span class="stat-icon">${icon(ic)}</span></div><div class="stat-number">${value}${unit?` <small>${unit}</small>`:''}</div><div class="stat-bottom">${note}</div></div>`}
function tabs(items,active,attr='tab'){return `<div class="tabs">${items.map(([id,label,count])=>`<button class="tab ${id===active?'active':''}" data-${attr}="${id}">${label}${count!==undefined?`<span class="tab-count">${count}</span>`:''}</button>`).join('')}</div>`}
function search(placeholder='Buscar por nombre, código o lote…'){return `<label class="search">${icon('search')}<input id="search" type="search" aria-label="Buscar" placeholder="${placeholder}" value="${esc(query)}"></label>`}
function options(values,selected,blank){return `<option value="">${blank}</option>`+values.map(v=>`<option ${v===selected?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}
function empty(title,sub,action=''){return `<div class="empty">${icon(view==='ordenes'?'file':'box')}<h3>${title}</h3><p>${sub}</p>${action}</div>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>`}
function pager(total,label='lotes'){const pages=Math.max(1,Math.ceil(total/perPage));page=Math.min(page,pages);let visible=Array.from({length:pages},(_,i)=>i+1).filter(n=>n===1||n===pages||Math.abs(n-page)<=1);return `<div class="table-footer"><span>Mostrando <b>${total?((page-1)*perPage+1):0}–${Math.min(total,page*perPage)}</b> de <b>${total}</b> ${label}</span><div class="pagination"><button class="page-btn" data-page="${page-1}" ${page===1?'disabled':''} aria-label="Página anterior">‹</button>${visible.map((n,i)=>`${i&&n-visible[i-1]>1?'<span>…</span>':''}<button class="page-btn ${n===page?'selected':''}" data-page="${n}">${n}</button>`).join('')}<button class="page-btn" data-page="${page+1}" ${page===pages?'disabled':''} aria-label="Página siguiente">›</button></div></div>`}
function slice(rows){page=Math.min(page,Math.max(1,Math.ceil(rows.length/perPage)));return rows.slice((page-1)*perPage,page*perPage)}
function monthInput(){return `<div class="month-control">${icon('calendar').replace('<svg ','<svg width="16" height="16" ')}<input type="month" id="month" aria-label="Mes" value="${month}"></div>`}
function render(){if(!data)return;document.querySelector('#navigation').innerHTML=navs.map(([id,ic,label])=>`<a class="nav-item ${view===id?'active':''}" href="#${id}">${icon(ic)}${label}${id==='inventario'?`<span class="nav-badge">${data.lots.length}</span>`:''}</a>`).join('');document.querySelector('#breadcrumb').textContent=navs.find(n=>n[0]===view)[2];main.innerHTML=(readOnly?'<div class="notice"><strong>Vista previa del piloto.</strong> Puedes explorar las pantallas y exportar el inventario del PDF. Guardar movimientos, productos y órdenes requiere conectar la base de datos; aquí no se guardan cambios.</div>':'')+({inventario:inventory,movimientos:movements,catalogo:catalog,ordenes:orders,preparacion:preparations,cortes:cuts}[view])();bind()}
function containerMarkup(l){
  if(l.category!=='tinta')return `<span class="form-hint">${num(l.grams)} piezas</span>`;
  if(l.grams<0)return '<span class="negative-note">Saldo negativo pendiente de revisión. No se generan garrafones.</span>';
  const containers=splitContainers(l.grams);
  if(!containers.length)return '<span class="form-hint">Sin garrafones con existencia.</span>';
  return `<div class="containers">${containers.map(c=>`<div class="container-chip ${c.grams<4000?'partial':''}"><span class="jug-icon">${icon('box')}</span><div><strong>Garrafón ${c.number}</strong><span>${num(c.grams)} / 4,000 g</span></div><span class="container-level"><i style="height:${c.grams/4000*100}%"></i></span></div>`).join('')}</div>`;
}
function groupMarkup(group){
  return `<details class="product-group" open><summary><span class="group-title">${ink(group)}</span><span class="type-badge ${group.kind==='UV'?'uv':''}">${esc(group.kind)}</span><span class="group-provider">${esc(group.provider)}</span><span class="chip">${group.lots.length} ${group.lots.length===1?'lote':'lotes'}</span><span class="group-stock stock ${group.grams<0?'negative':''}">${num(group.grams)} <span class="unit">${group.category==='tinta'?'g':'pzas'}</span></span><span class="expand-chevron">⌄</span></summary><div class="group-lots">${group.lots.map(l=>`<article class="lot-block"><div class="lot-heading"><div><span class="lot-label">LOTE</span> <strong>${esc(l.lot)}</strong><span class="lot-entry">Entrada: ${displayDate(l.entry_date)}</span></div><div class="lot-heading-right">${badge(l)}<span class="stock ${l.grams<0?'negative':''}">${num(l.grams)} <span class="unit">${l.category==='tinta'?'g':'pzas'}</span></span><button class="btn lot-details" data-detail="${l.id}">Ver lote</button></div></div>${containerMarkup(l)}</article>`).join('')}</div></details>`;
}
function visibleInventoryLots(){
 return data.lots.filter(l=>l.category===tab&&`${l.name} ${l.code} ${l.lot}`.toLowerCase().includes(query.toLowerCase())&&(!typeFilter||l.kind===typeFilter)&&(!providerFilter||l.provider===providerFilter)&&(!statusFilter||(statusFilter==='negative'?l.grams<0:status(l)[1]===statusFilter)));
}
function providerMarkup(provider){
 return `<details class="provider-group" open><summary><span class="provider-icon">${icon('box')}</span><div class="provider-title"><strong>${esc(provider.name)}</strong><small>${provider.groups.length} códigos · ${provider.lots.length} lotes</small></div><span class="provider-total">${num(provider.grams)} <span class="unit">${tab==='tinta'?'g':'pzas'}</span></span><span class="expand-chevron">⌄</span></summary><div class="provider-content">${provider.groups.map(groupMarkup).join('')}</div></details>`;
}
function inventory(){
 const lots=data.lots.filter(l=>l.category===tab),expired=lots.filter(l=>days(l)<0&&l.category==='tinta'),negative=lots.filter(l=>l.grams<0);
 const filtered=visibleInventoryLots();
 const groups=groupLots(filtered);
 return header('CONTROL DE EXISTENCIAS','Tu inventario, al día.','Por proveedor, código, lote y garrafón. Todo tu inventario en una sola lista.',button('Exportar PDF','export','download')+button('Registrar ingreso','income','plus',true))+
 `<section class="stats">${stat('Tintas en existencia',num(groupLots(lots).length),'',`${lots.length} lotes registrados`)}${stat('Existencia total',num(lots.reduce((s,l)=>s+l.grams,0)/(tab==='tinta'?1000:1)),tab==='tinta'?'kg':'pzas','Saldo neto de los lotes registrados','grid')}${stat('Valor del inventario',money(lots.reduce((s,l)=>s+l.grams*l.cost_kg/(tab==='tinta'?1000:1),0)),'','Valorado al costo de cada lote','money')}${stat(tab==='tinta'?'Lotes vencidos':'Sin existencia',num(tab==='tinta'?expired.length:lots.filter(l=>l.grams<=0).length),'',tab==='tinta'?'Revisa su uso antes de producir':'Revisa las existencias disponibles','clock','amber')}</section>`+
 (negative.length?`<div class="warning-banner">${icon('warning')}<span><strong>${negative.length} lotes necesitan revisión.</strong> Se conservan los saldos negativos del inventario inicial.</span><button data-action="negative">Ver lotes →</button></div>`:'')+
 `<section class="panel"><div class="panel-heading"><div><h2>Inventario por proveedor</h2><p>Despliega un proveedor para consultar todos sus códigos, lotes y garrafones.</p></div><span class="chip">${groupLots(lots).length} códigos</span></div>${tabs([['tinta','Tintas',data.lots.filter(l=>l.category==='tinta').length],['herramental','Herramentales',data.lots.filter(l=>l.category==='herramental').length]],tab)}<div class="toolbar">${search()}<select id="type-filter" class="filter" aria-label="Tipo">${options([...new Set(lots.map(l=>l.kind))],typeFilter,'Todos los tipos')}</select><select id="provider-filter" class="filter" aria-label="Proveedor">${options([...new Set(lots.map(l=>l.provider))],providerFilter,'Todos los proveedores')}</select><span class="spacer"></span><select id="status-filter" class="filter" aria-label="Estado">${options(['Vigente','Por vencer','Vencida','Disponible','Sin existencia','negative'],statusFilter,'Todos los estados').replace('>negative<','>Saldo negativo<')}</select></div>${tab==='tinta'?'<div class="distribution-notice">Garrafones de 4 kg · Distribución inicial estimada: 4,000 g por garrafón y un último con el sobrante. Pendiente de verificación física; se recalcula a partir del saldo del lote.</div>':''}${groups.length?`<div class="inventory-groups">${groupByProvider(filtered).map(providerMarkup).join('')}</div>`:empty(tab==='herramental'?'Agrega tus primeros herramentales':'No encontramos lotes','Registra un ingreso o cambia los filtros para ver tus materiales.',button('Registrar ingreso','income','plus',true))}<div class="table-footer"><span><b>${filtered.length}</b> de ${lots.length} lotes · <b>${groups.length}</b> códigos · <b>${groupByProvider(filtered).length}</b> proveedores · Sin límite de visualización</span><div class="list-controls"><button class="btn" data-action="expand-all">Expandir todo</button><button class="btn" data-action="collapse-all">Contraer todo</button></div></div></section><div class="helper-line"><span>${icon('info')} Las salidas y órdenes descuentan del lote. Los garrafones muestran un reparto estimado del saldo.</span><span>Unidad: ${tab==='tinta'?'gramos (g)':'piezas'} · Moneda: MXN</span></div>`;
}
function movements(){const rows=data.movements.filter(m=>(movementTab==='all'||m.type===movementTab)&&`${m.name} ${m.lot} ${m.reason}`.toLowerCase().includes(query.toLowerCase())&&m.date.slice(0,7)===month);const current=data.movements.filter(m=>m.date.slice(0,7)===month);return header('TRAZABILIDAD DE MATERIALES','Ingresos y egresos','El historial de cada entrada, salida y consumo de producción.',button('Registrar egreso','expense','arrows')+button('Registrar ingreso','income','plus',true))+`<section class="stats">${stat('Ingresos del mes',num(current.filter(m=>m.type==='in').length),'','Entradas registradas','arrows')}${stat('Egresos del mes',num(current.filter(m=>m.type==='out').length),'','Incluye consumo de producción','arrows')}${stat('Movimientos',num(current.length),'',monthLabel(month),'clock')}${stat('Carga inicial',num(current.filter(m=>m.type==='initial').length),'','Lotes importados del PDF','file')}</section><section class="panel"><div class="panel-heading"><div><h2>Historial de movimientos</h2><p>Cada movimiento conserva su fecha, lote y motivo.</p></div>${monthInput()}</div>${tabs([['all','Todos'],['in','Ingresos'],['out','Egresos'],['initial','Carga inicial']],movementTab,'movement-tab')}<div class="toolbar">${search('Buscar tinta, lote o motivo…')}<span class="spacer"></span>${button('Exportar PDF','export','download')}</div>${rows.length?table(['FECHA','TINTA / MATERIAL','LOTE','MOVIMIENTO','CANTIDAD','MOTIVO'],slice(rows).map(m=>`<tr><td>${displayDate(m.date)}</td><td>${ink(m)}</td><td>${esc(m.lot)}</td><td><span class="status ${m.type==='out'?'expired':m.type==='initial'?'neutral':''}">${{in:'Ingreso',out:'Egreso',initial:'Carga inicial'}[m.type]}</span></td><td class="stock ${m.type==='out'?'negative':''}">${m.type==='out'?'−':m.type==='in'?'+':''}${num(m.grams)} <span class="unit">${data.lots.find(l=>l.id===m.lot_id)?.category==='herramental'?'pzas':'g'}</span></td><td>${esc(m.reason)}</td></tr>`).join('')):empty('Sin movimientos en este período','Los movimientos que registres aparecerán aquí con todo su detalle.')}${pager(rows.length,'movimientos')}</section>`}
function catalog(){const products=data.products.filter(p=>p.category===catalogTab&&`${p.name} ${p.code} ${p.provider}`.toLowerCase().includes(query.toLowerCase()));return header('BIBLIOTECA DE MATERIALES','Catálogo de productos','Una ficha para cada tinta y herramental de tu operación.',button('Exportar PDF','export','download')+button('Nuevo producto','product','plus',true))+`<section class="panel"><div class="panel-heading"><div><h2>Tu catálogo</h2><p>Los ingresos de productos nuevos los dan de alta automáticamente.</p></div><span class="chip">${data.products.length} productos</span></div>${tabs([['tinta','Tintas',data.products.filter(p=>p.category==='tinta').length],['herramental','Herramentales',data.products.filter(p=>p.category==='herramental').length]],catalogTab,'catalog-tab')}<div class="toolbar">${search('Buscar producto, código o proveedor…')}</div>${products.length?`<div class="catalog-grid">${products.map(p=>{const ls=data.lots.filter(l=>l.product_id===p.id);return `<article class="catalog-card">${ink(p)}<div class="catalog-meta"><span>${esc(p.provider)}</span><span class="type-badge ${p.kind==='UV'?'uv':''}">${esc(p.kind)}</span></div><div class="catalog-meta"><span>${ls.length} lotes</span><strong class="stock">${num(ls.reduce((s,l)=>s+l.grams,0))} ${p.category==='tinta'?'g':'pzas'}</strong></div><div class="catalog-meta"><span>Punto de recompra</span><span>${num(p.minimum)} ${p.category==='tinta'?'g':'pzas'}</span></div><div class="catalog-meta"><span>Máximo</span><span>${num(p.maximum||0)} ${p.category==='tinta'?'g':'pzas'}</span></div><div class="catalog-meta"><span>Caducidad</span><span>${num(p.shelf_days||365)} días</span></div><div class="catalog-meta"><span>Costo de catálogo / ${p.category==='tinta'?'kg':'pieza'}</span><strong>${money(p.cost_kg||0)}</strong></div></article>`}).join('')}</div>`:empty('Tu catálogo está por crecer','Agrega un producto o registra su primer ingreso.',button('Nuevo producto','product','plus',true))}</section>`}
function productionRows(orders){return orders.flatMap(o=>o.lines.map(line=>({order:o,line})));}
function filteredProductionOrders(){return data.orders.filter(o=>o.date.slice(0,7)===month);}
function filteredProductionRows(){return productionRows(filteredProductionOrders()).filter(({order:o,line:l})=>`${o.folio} ${o.client} ${o.product||''} ${o.pressman||''} ${l.np||''} ${l.name} ${l.code} ${l.lot} ${l.notes||''}`.toLowerCase().includes(query.toLowerCase()));}
function orderStatus(o){return `<span class="status ${o.status==='cancelled'?'neutral':o.status==='draft'?'warning':''}">${o.status==='cancelled'?'Cancelada':o.status==='draft'?'Pendiente':'Confirmada'}</span>`;}
function weight(v){return v===null||v===undefined?'—':num(v);}
function productionTable(rows){return table(['ORDEN','NP','FECHA','PRENSISTA','TINTA','LOTE','INGRESO (g)','EGRESO (g)','GRAMOS TOTALES','METROS','NOTAS','PRODUCTO','ESTADO',''],rows.map(({order:o,line:l})=>`<tr><td><strong>${esc(o.folio)}</strong></td><td>${esc(l.np||'—')}</td><td>${displayDate(o.date)}</td><td>${esc(o.pressman||'—')}</td><td>${ink(l)}</td><td>${esc(l.lot)}</td><td class="mono">${weight(l.initial_grams)}</td><td class="mono">${weight(l.final_grams)}</td><td class="stock">${l.initial_grams!=null&&l.final_grams==null?'Pendiente':num(l.grams)}${o.status==='draft'?' *':''}</td><td>${weight(l.meters)}</td><td class="production-note">${esc(l.notes||o.notes||'—')}</td><td>${esc(o.product||o.client)}</td><td>${orderStatus(o)}</td><td><button class="btn" data-order-detail="${o.id}">${o.status==='draft'?'Completar':'Ver registro'}</button></td></tr>`).join(''));}
function orders(){const rows=filteredProductionRows(),orders=[...new Map(rows.map(r=>[r.order.id,r.order])).values()],active=rows.filter(r=>r.order.status==='confirmed');return header('REGISTRO DE PRODUCCIÓN','Órdenes de producción','El formato de tu planta: pesos de entrada y salida, tinta por tinta.',button('Exportar PDF','export','download')+button('Nuevo registro','order','plus',true))+`<section class="stats">${stat('Registros del mes',num(orders.length),'',monthLabel(month),'file')}${stat('Pendientes de completar',num(orders.filter(o=>o.status==='draft').length),'','Sin descuento de inventario','clock','amber')}${stat('Tinta consumida',num(active.reduce((s,r)=>s+r.line.grams,0)/1000),'kg','Solo registros confirmados','box')}${stat('Costo de tintas',money(active.reduce((s,r)=>s+r.line.grams*r.line.cost_kg/1000,0)),'','Consumo de los lotes utilizados','money')}</section><section class="panel"><div class="panel-heading"><div><h2>Bitácora de producción por mes</h2><p>Un renglón por tinta y lote, como en tu hoja de trabajo.</p></div>${monthInput()}</div><div class="toolbar">${search('Buscar orden, NP, prensista, tinta o producto…')}<span class="spacer"></span><span class="chip">${monthLabel(month)}</span></div><div class="distribution-notice">Ingreso = peso inicial · Egreso = peso final / devuelto · Gramos totales = ingreso − egreso. Solo esa diferencia se descuenta al confirmar. * Los registros pendientes todavía no afectan las existencias.</div>${rows.length?productionTable(slice(rows)):productionTable([])+empty('Registra tu siguiente producción','Captura la orden, NP, prensista y producto. Agrega cada tinta con sus pesos inicial y final.',button('Nuevo registro','order','plus',true))}${pager(rows.length,'renglones')}</section>`;}
function preparationRows(){return (data.preparations||[]).filter(p=>p.date.slice(0,7)===month&&`${p.folio} ${p.np} ${p.supplies} ${p.product} ${p.notes}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>a.date.localeCompare(b.date)||a.start_time.localeCompare(b.start_time));}
function preparations(){const rows=preparationRows(),total=rows.reduce((s,p)=>s+Number(p.minutes),0);return header('TIEMPOS Y ORGANIZACIÓN','Preparación de órdenes','Registra el tiempo que toma dejar cada trabajo listo para producción.',button('Exportar PDF','export','download')+button('Registrar preparación','preparation','plus',true))+`<section class="stats">${stat('Preparaciones del mes',num(rows.length),'',monthLabel(month),'file')}${stat('Tiempo total',num(total),'min','Tiempo de preparación registrado','clock')}${stat('Tiempo promedio',num(rows.length?total/rows.length:0),'min','Promedio por registro','arrows')}${stat('Órdenes preparadas',num(new Set(rows.map(p=>p.folio)).size),'','Órdenes diferentes en el período','check')}</section><section class="panel"><div class="panel-heading"><div><h2>Bitácora de preparación</h2><p>Fechas, horarios, insumos y observaciones de cada orden.</p></div>${monthInput()}</div><div class="toolbar">${search('Buscar orden, NP, insumos o producto…')}<span class="spacer"></span><span class="chip">${rows.length} registros</span></div>${table(['FECHA','ORDEN','NP','HORA DE INICIO','HORA DE FIN','PREPARACIÓN (min)','FECHA SOLICITADA','HORA SOLICITADA','INSUMOS / HERRAMENTAL PREPARADO','PRODUCTO','OBSERVACIONES',''],rows.map(p=>`<tr><td>${displayDate(p.date)}</td><td><strong>${esc(p.folio)}</strong></td><td>${esc(p.np)}</td><td>${esc(p.start_time)}</td><td>${esc(p.end_time)}${p.end_next_day?'<span class="ink-code">Día siguiente</span>':''}</td><td class="stock">${num(p.minutes)} <span class="unit">min</span></td><td>${p.requested_date?displayDate(p.requested_date):'—'}</td><td>${esc(p.requested_time||'—')}</td><td class="production-note">${esc(p.supplies)}</td><td>${esc(p.product)}</td><td class="production-note">${esc(p.notes||'—')}</td><td><button class="btn" data-preparation="${p.id}">Editar</button></td></tr>`).join(''))}${rows.length?'':empty('Registra tu primera preparación','Captura las horas de inicio y fin: calcularemos los minutos automáticamente, sin modificar tus existencias.',button('Registrar preparación','preparation','plus',true))}<div class="table-footer">${rows.length} registros · Total ${num(total)} min · Estos registros no descuentan materiales del inventario.</div></section>`;}
function preparationForm(id=null){
 const existing=(data.preparations||[]).find(p=>p.id===id);
 show(existing?'Editar preparación':'Registrar preparación','El tiempo se calcula con las horas de inicio y fin.',`<div class="form-grid">${field('Fecha de preparación','date','date',existing?.date||data.today,`required max="${data.today}"`)}${field('Orden','folio','text',existing?.folio||'','required maxlength="100"')}${field('NP','np','text',existing?.np||'','required maxlength="100"')}${field('Producto','product','text',existing?.product||'','required maxlength="150"')}${field('Hora de inicio','start_time','time',existing?.start_time||'','required step="1"')}${field('Hora de fin','end_time','time',existing?.end_time||'','required step="1"')}<label class="field full"><span><input class="inline-checkbox" name="end_next_day" type="checkbox" ${existing?.end_next_day?'checked':''}> Termina al día siguiente</span></label>${field('Fecha solicitada (opcional)','requested_date','date',existing?.requested_date||'')}${field('Hora solicitada (opcional)','requested_time','time',existing?.requested_time||'','step="1"')}<label class="field full">Insumos / herramental preparado<textarea name="supplies" required maxlength="2000" placeholder="Ejemplo: 4 placas, 4 tintas, 4 charolas, 1 suaje…">${esc(existing?.supplies||'')}</textarea></label><label class="field full">Observaciones<textarea name="notes" maxlength="2000" placeholder="Detalles, retrasos o comentarios de la preparación…">${esc(existing?.notes||'')}</textarea></label></div><div class="cost-preview">Tiempo de preparación<strong id="preparation-total">Captura las horas</strong></div><p class="form-hint">El tiempo se guarda en minutos. Este registro documenta la preparación; no genera consumos de inventario.</p>`,'Guardar preparación',async f=>{
  const body={...Object.fromEntries(f),end_next_day:modal.querySelector('[name=end_next_day]').checked};if(existing)body.id=existing.id;
  await post('preparations',body);month=body.date.slice(0,7);render();toast('Tiempo de preparación guardado.');
 });
 const update=()=>{const form=modal.querySelector('form'),end=form.querySelector('[name=end_time]');end.setCustomValidity('');try{const minutes=preparationMinutes(form.querySelector('[name=start_time]').value,end.value,form.querySelector('[name=end_next_day]').checked);modal.querySelector('#preparation-total').textContent=num(minutes)+' min';}catch(error){modal.querySelector('#preparation-total').textContent='Revisa las horas';if(form.querySelector('[name=start_time]').value&&end.value)end.setCustomValidity(error.message);}};
 modal.querySelector('form').addEventListener('input',update);update();
}
function monthlyRows(){return data.lots.map(l=>{let opening=0,incoming=0,outgoing=0;for(const m of data.movements.filter(m=>m.lot_id===l.id&&m.date.slice(0,7)<=month)){if(m.date.slice(0,7)<month||m.type==='initial')opening+=m.type==='out'?-m.grams:m.grams;else if(m.type==='in')incoming+=m.grams;else outgoing+=m.grams}return {...l,opening,incoming,outgoing,closing:opening+incoming-outgoing}})}
function cuts(){const saved=data.cuts.find(c=>c.month===month),rows=saved?saved.snapshot:monthlyRows(),inks=rows.filter(l=>l.category==='tinta'),closed=!!saved,noHistory=month<data.baseline.slice(0,7);const filtered=rows.filter(l=>`${l.name} ${l.code} ${l.lot}`.toLowerCase().includes(query.toLowerCase()));return header('CIERRE Y CONTROL MENSUAL','Cada mes, cuentas claras.','Revisa las entradas, los consumos y el saldo final de cada lote.',button('Exportar corte PDF','export','download')+button(closed?'Mes cerrado':'Cerrar mes','close-month','calendar',true,closed?'disabled':''))+`<section class="stats">${stat('Existencia inicial',num(inks.reduce((s,l)=>s+l.opening,0)/1000),'kg','Saldo inicial registrado','box')}${stat('Ingresos del mes',num(inks.reduce((s,l)=>s+l.incoming,0)/1000),'kg','Entradas y devoluciones','arrows')}${stat('Egresos del mes',num(inks.reduce((s,l)=>s+l.outgoing,0)/1000),'kg','Salidas y producción','arrows')}${stat('Existencia final',num(inks.reduce((s,l)=>s+l.closing,0)/1000),'kg','Inicial + ingresos − egresos','check')}</section><section class="panel"><div class="panel-heading"><div><h2>${closed?'Corte definitivo':'Resumen del mes'}</h2><p>${monthLabel(month)}</p></div>${monthInput()}</div><div class="cut-info">${noHistory?'No hay historia anterior a la carga inicial del '+displayDate(data.baseline)+'.':closed?`<strong>Mes cerrado.</strong> Este corte conserva los saldos al cierre y bloquea movimientos en el período.`:`<strong>Resumen en curso.</strong> El corte definitivo está disponible al terminar el mes. La carga inicial se considera saldo de apertura; no reconstruye movimientos anteriores al ${displayDate(data.baseline)}.`}</div><div class="toolbar">${search()}<span class="spacer"></span><span class="status ${closed?'':'neutral'}">${closed?'Cerrado':'Sin cierre definitivo'}</span></div>${noHistory?empty('No hay movimientos históricos','El piloto inicia con las existencias del PDF.'):table(['TINTA / MATERIAL','LOTE','INICIAL','INGRESOS','EGRESOS','FINAL','VALOR FINAL'],slice(filtered).map(l=>`<tr><td>${ink(l)}</td><td>${esc(l.lot)}</td><td>${num(l.opening)}</td><td>${num(l.incoming)}</td><td>${num(l.outgoing)}</td><td class="stock ${l.closing<0?'negative':''}">${num(l.closing)} <span class="unit">${l.category==='tinta'?'g':'pzas'}</span></td><td>${money(l.closing*l.cost_kg/(l.category==='tinta'?1000:1))}</td></tr>`).join(''))}${noHistory?'':pager(filtered.length)}</section>`}
function bind(){main.querySelectorAll('[data-preparation]').forEach(el=>el.onclick=()=>preparationForm(Number(el.dataset.preparation)));document.querySelector('#search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;query=e.target.value;page=1;render();const el=document.querySelector('#search');el.focus();if(el.type!=='search')el.setSelectionRange(pos,pos)});for(const [id,key] of [['type-filter','type'],['provider-filter','provider'],['status-filter','status']])document.getElementById(id)?.addEventListener('change',e=>{if(key==='type')typeFilter=e.target.value;if(key==='provider')providerFilter=e.target.value;if(key==='status')statusFilter=e.target.value;page=1;render()});document.querySelector('#month')?.addEventListener('change',e=>{if(e.target.value){month=e.target.value;page=1;render()}});main.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{tab=el.dataset.tab;page=1;query='';typeFilter='';providerFilter='';statusFilter='';render()});main.querySelectorAll('[data-catalog-tab]').forEach(el=>el.onclick=()=>{catalogTab=el.dataset.catalogTab;query='';render()});main.querySelectorAll('[data-movement-tab]').forEach(el=>el.onclick=()=>{movementTab=el.dataset.movementTab;page=1;render()});main.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{page=Number(el.dataset.page);render()});main.querySelectorAll('[data-detail]').forEach(el=>el.onclick=()=>lotDetail(Number(el.dataset.detail)));main.querySelectorAll('[data-order-detail]').forEach(el=>el.onclick=()=>orderDetail(Number(el.dataset.orderDetail)));main.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action))}
function action(a){if(a==='preparation')preparationForm();if(a==='income')movementForm('in');if(a==='expense')movementForm('out');if(a==='product')productForm();if(a==='order')orderForm();if(a==='negative'){statusFilter='negative';page=1;render()}if(a==='export')exportPDF();if(a==='expand-all'||a==='collapse-all')main.querySelectorAll('.provider-group,.product-group').forEach(el=>el.open=a==='expand-all');if(a==='close-month')closeForm()}
function show(title,sub,body,submit='',callback){modal.classList.remove('wide-modal');modal.innerHTML=`<form id="modal-form"><div class="modal-header"><div><h2>${title}</h2><p>${sub}</p></div><button type="button" class="icon-button" data-dismiss aria-label="Cerrar">${icon('x')}</button></div><div class="modal-body">${body}<p class="form-error" id="form-error" role="alert" hidden></p></div><div class="modal-actions"><button type="button" class="btn" data-dismiss>${submit?'Cancelar':'Cerrar'}</button>${submit?`<button type="submit" class="btn primary" id="submit-button">${submit}</button>`:''}</div></form>`;modal.querySelectorAll('[data-dismiss]').forEach(el=>el.onclick=()=>modal.close());modal.querySelector('form').onsubmit=async e=>{e.preventDefault();const btn=modal.querySelector('#submit-button'),err=modal.querySelector('#form-error');if(!callback)return;btn.disabled=true;err.hidden=true;try{await callback(new FormData(e.target));modal.close()}catch(error){err.textContent=error.message;err.hidden=false;btn.disabled=false}};if(!modal.open)modal.showModal()}
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
function field(label,name,type='text',value='',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function selectField(label,name,opts,extra=''){return `<label class="field">${label}<select name="${name}" ${extra}>${opts}</select></label>`}
function productFields(){return `<div class="form-grid">${field('Nombre / color','name','text','','required maxlength="100"')}${field('Código único','code','text','','required maxlength="60"')}${selectField('Categoría','category','<option value="tinta">Tinta</option><option value="herramental">Herramental</option>')}${field('Tipo (Base Agua, UV, anilox…)','kind','text','Base Agua','required maxlength="50"')}${field('Proveedor','provider','text','','required maxlength="100"')}${field('Existencia mínima (g o piezas)','minimum','number','1000','required min="0" step="0.001"')}</div>`}
function productForm(){show('Nuevo producto','Crea una ficha de tinta o herramental para tu catálogo.',productFields(),'Guardar producto',async f=>{const b=Object.fromEntries(f);if(data.products.some(p=>canonicalCode(p.code)===canonicalCode(b.code)))throw Error('Ese código ya está en tu catálogo.');await post('products',b);toast('Producto guardado en el catálogo.')})}
function movementForm(type,mode='existing',fixedLot){const income=type==='in';const selected=fixedLot||data.lots.find(l=>income||l.grams>0)?.id;const lotOptions=data.lots.filter(l=>income||l.grams>0).map(l=>`<option value="${l.id}" ${l.id===selected?'selected':''}>${esc(l.name)} · ${esc(l.code)} · Lote ${esc(l.lot)} (${num(l.grams)} ${l.category==='tinta'?'g':'pzas'})</option>`).join('');const productOptions=data.products.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.code)}</option>`).join('');const body=(income?`<div class="switch-row"><button type="button" class="btn ${mode==='existing'?'chosen':''}" data-mode="existing">Lote existente</button><button type="button" class="btn ${mode==='lot'?'chosen':''}" data-mode="lot">Nuevo lote</button><button type="button" class="btn ${mode==='new'?'chosen':''}" data-mode="new">Nueva tinta / material</button></div>`:'')+(mode==='new'?productFields():'')+`<div class="form-grid" style="margin-top:${mode==='new'?20:0}px">${mode==='existing'?`<div class="field full">${selectField('Selecciona el lote','lot_id',lotOptions,'required')}</div>`:mode==='lot'?`<div class="field full">${selectField('Producto del catálogo','product_id',productOptions,'required')}</div>`:''}${mode!=='existing'?field('Número de lote / identificación','lot','text','','required')+field('Vida útil en días (0 para herramental)','shelf_days','number','365','min="0" max="36500" step="1" required')+field('Costo por kg / por pieza (MXN)','cost_kg','number','','min="0" step="0.01" required'):''}${field('Cantidad (gramos o piezas)','grams','number','','min="0.001" step="0.001" required')}${field('Fecha del movimiento','date','date',data.today,`min="${data.baseline}" max="${data.today}" required`)}<label class="field full">Motivo / referencia<input name="reason" required maxlength="200" placeholder="${income?'Compra, devolución, ajuste de inventario…':'Muestra, merma, ajuste de inventario…'}"></label></div><div class="cost-preview" id="movement-cost">${income?'Ingreso al inventario':'Salida del inventario'}<strong>Captura una cantidad</strong></div><p class="form-hint">${mode==='new'?'El producto y su lote se darán de alta automáticamente al guardar. ':''}${income?'Si ingresas al mismo lote, se conserva su costo registrado.':'No se permiten salidas mayores a la existencia disponible.'}</p>`;show(income?'Registrar ingreso':'Registrar egreso',income?'Registra una entrada y actualiza las existencias.':'Registra una salida con su lote y motivo.',body,income?'Guardar ingreso':'Guardar egreso',async f=>{const b={...Object.fromEntries(f),type};await post('movements',b);toast(income?'Ingreso registrado. Inventario actualizado.':'Egreso registrado. Inventario actualizado.')});modal.querySelectorAll('[data-mode]').forEach(el=>el.onclick=()=>movementForm(type,el.dataset.mode));const preview=()=>{const f=new FormData(modal.querySelector('form')),lot=data.lots.find(l=>l.id===Number(f.get('lot_id'))),p=data.products.find(p=>p.id===Number(f.get('product_id')));const cat=lot?.category||p?.category||f.get('category')||'tinta';const qty=Number(f.get('grams')||0),cost=lot?.cost_kg??Number(f.get('cost_kg')||0);modal.querySelector('#movement-cost').innerHTML=`${num(qty)} ${cat==='tinta'?'gramos':'piezas'} · Valor del movimiento<strong>${money(qty*cost/(cat==='tinta'?1000:1))}</strong>`};modal.querySelector('form').addEventListener('input',preview);const productSelect=modal.querySelector('[name=product_id]');if(productSelect){const applyDefaults=()=>{const p=data.products.find(p=>p.id===Number(productSelect.value));if(p){modal.querySelector('[name=shelf_days]').value=p.shelf_days??365;modal.querySelector('[name=cost_kg]').value=p.cost_kg??0;preview()}};productSelect.addEventListener('change',applyDefaults);applyDefaults()}preview()}
function orderForm(existingId=null){
 const existing=existingId?data.orders.find(o=>o.id===existingId):null;
 const eligible=data.lots.filter(l=>l.category==='tinta'&&(l.grams>0||existing?.lines.some(i=>i.lot_id===l.id)));
 if(!eligible.length){toast('No hay lotes de tinta con existencia disponible.');return;}
 show(existing?'Completar registro de producción':'Nuevo registro de producción','Captura los pesos como en tu hoja. El consumo se calcula automáticamente.',`<div class="form-grid production-fields">${field('Orden / órdenes de producción','folio','text',existing?.folio||`OP-${data.today.slice(0,4)}-${String(data.orders.length+1).padStart(5,'0')}`,'required maxlength="100"')}${field('Fecha','date','date',existing?.date||data.today,`required min="${data.baseline}" max="${data.today}"`)}${field('Prensista','pressman','text',existing?.pressman||'','required maxlength="100"')}${field('Producto','product','text',existing?.product||'','required maxlength="150"')}${field('Cliente (opcional)','client','text',existing?.client||'','maxlength="150"')}${selectField('Guardar como','status','<option value="confirmed">Confirmado · descontar consumo</option><option value="draft">Pendiente · sin descontar inventario</option>')}</div><div class="section-label">TINTAS Y PESOS · CANTIDADES EN GRAMOS</div><div class="order-lines-scroll"><div id="order-lines"></div></div><button type="button" class="btn" id="add-line">${icon('plus')}Agregar tinta</button><div class="cost-preview">Consumo calculado<strong id="order-total">0 g · $0.00</strong></div><label class="field" style="margin-top:17px">Notas generales<textarea name="notes" maxlength="1000">${esc(existing?.notes||'')}</textarea></label><p class="form-hint">Ingreso es el peso inicial y egreso el peso final o devuelto. No son dos movimientos de inventario: se descuenta únicamente la diferencia al confirmar. Si falta el peso final, guarda como pendiente. Los lotes vencidos se señalan para revisión.</p>`,'Guardar registro',async f=>{
  const lines=[...modal.querySelectorAll('.order-line')].map(el=>Object.fromEntries([...el.querySelectorAll('input,select')].filter(e=>e.name).map(e=>[e.name,e.value])));
  const b={...Object.fromEntries(f),capture_mode:'weighing',lines};if(existing)b.id=existing.id;
  await post(existing?'orders/update':'orders',b);month=b.date.slice(0,7);page=1;render();toast(b.status==='draft'?'Registro pendiente guardado. No se descontó tinta.':'Registro confirmado. Solo se descontó el consumo calculado.');
 });
 modal.classList.add('wide-modal');
 const total=()=>{
  let grams=0,cost=0,pending=0;
  const draft=modal.querySelector('[name=status]').value==='draft';
  modal.querySelectorAll('.order-line').forEach(el=>{
   const initial=el.querySelector('[name=initial_grams]'),final=el.querySelector('[name=final_grams]');final.required=!draft;
   const hasInitial=initial.value!==''&&Number.isFinite(Number(initial.value)),hasFinal=final.value!==''&&Number.isFinite(Number(final.value));
   final.setCustomValidity(hasInitial&&hasFinal&&Number(final.value)>Number(initial.value)?'El peso final no puede superar al inicial.':'');
   const g=hasInitial&&hasFinal?Math.round((Number(initial.value)-Number(final.value))*1000)/1000:null;
   el.querySelector('.line-consumed').textContent=g===null?'Pendiente':num(g)+' g';
   if(g!==null&&g>=0){grams+=g;const l=data.lots.find(l=>l.id===Number(el.querySelector('[name=lot_id]').value));cost+=g*(l?.cost_kg||0)/1000;}else pending++;
  });
  modal.querySelector('#order-total').textContent=`${num(grams)} g · ${money(cost)}${pending?' · '+pending+' sin peso final':''}`;
 };
 const add=(line={})=>{
  const row=document.createElement('div');row.className='order-line weighing-line';
  row.innerHTML=field('NP','np','text',line.np||'','required maxlength="100"')+selectField('Tinta · lote · disponible','lot_id',eligible.map(l=>`<option value="${l.id}" ${l.id===line.lot_id?'selected':''}>${esc(l.name)} · ${esc(l.lot)} · ${num(l.grams)} g${days(l)<0?' · VENCIDA':''}</option>`).join(''),'required')+field('Ingreso / inicial (g)','initial_grams','number',line.initial_grams??'','required min="0" step="0.001"')+field('Egreso / final (g)','final_grams','number',line.final_grams??'','min="0" step="0.001"')+'<div class="field">Gramos totales<output class="line-consumed">Pendiente</output></div>'+field('Metros','meters','number',line.meters??'','min="0" step="0.001"')+field('Notas del renglón','notes','text',line.notes||'','maxlength="500"')+`<button type="button" class="icon-button" aria-label="Eliminar tinta">${icon('x')}</button>`;
  row.querySelector('button').onclick=()=>{if(modal.querySelectorAll('.order-line').length>1){row.remove();total();}};row.addEventListener('input',total);modal.querySelector('#order-lines').append(row);total();
 };
 modal.querySelector('[name=status]').value=existing?.status==='draft'?'draft':'confirmed';
 modal.querySelector('[name=status]').addEventListener('change',total);
 modal.querySelector('#add-line').onclick=()=>add();
 if(existing){const cancel=document.createElement('button');cancel.type='button';cancel.className='btn danger';cancel.textContent='Cancelar registro pendiente';cancel.onclick=()=>show('Cancelar registro pendiente','No hay consumos descontados que devolver.','<p class="form-hint">Se conservará el registro con estado cancelado.</p>','Confirmar cancelación',async()=>{await post('orders/cancel',{id:existing.id});toast('Registro pendiente cancelado.');});modal.querySelector('.modal-actions').prepend(cancel);}
 if(existing)existing.lines.forEach(add);else add();
}
function lotDetail(id){const l=data.lots.find(l=>l.id===id),moves=data.movements.filter(m=>m.lot_id===id);show(esc(l.name),`Código ${esc(l.code)} · Lote ${esc(l.lot)}`,`${ink(l)}<div class="detail-grid"><div><small>Proveedor</small><strong>${esc(l.provider)}</strong></div><div><small>Tipo</small><strong>${esc(l.kind)}</strong></div><div><small>Existencia</small><strong>${num(l.grams)} ${l.category==='tinta'?'g':'pzas'}</strong></div><div><small>Valor de existencia</small><strong>${money(l.grams*l.cost_kg/(l.category==='tinta'?1000:1))}</strong></div><div><small>Fecha de entrada</small><strong>${displayDate(l.entry_date)}</strong></div><div><small>${l.category==='tinta'?'Caducidad':'Estado'}</small>${l.category==='tinta'?`<strong>${displayDate(new Date(Date.parse(l.entry_date)+l.shelf_days*86400000).toISOString().slice(0,10))}</strong><p>${badge(l)} · ${num(days(l))} días</p>`:badge(l)}</div></div><div class="section-label">GARRAFONES DE 4 KG · REPARTO ESTIMADO</div>${containerMarkup(l)}<p class="form-hint">Reparto calculado a partir del saldo; pendiente de verificar físicamente.</p><div class="section-label">MOVIMIENTOS DEL LOTE</div>${table(['FECHA','TIPO','CANTIDAD'],moves.map(m=>`<tr><td>${displayDate(m.date)}</td><td>${{in:'Ingreso',out:'Egreso',initial:'Carga inicial'}[m.type]}</td><td>${num(m.grams)}</td></tr>`).join(''))}<div class="actions" style="margin-top:20px">${button('Registrar ingreso','lot-in','plus',true)}${button('Registrar egreso','lot-out','arrows')}</div>`);modal.querySelector('[data-action="lot-in"]').onclick=()=>movementForm('in','existing',id);modal.querySelector('[data-action="lot-out"]').onclick=()=>movementForm('out','existing',id)}
function orderDetail(id){const o=data.orders.find(o=>o.id===id);if(o.status==='draft'){orderForm(id);return;}show(esc(o.folio),`${esc(o.product||o.client)} · ${displayDate(o.date)}`,`<div class="notice">${o.status==='cancelled'?'Registro cancelado. Si tenía consumos confirmados, fueron devueltos.':'Registro confirmado. Se descontó únicamente la diferencia entre peso inicial y final.'}</div><div class="detail-grid"><div><small>Prensista</small><strong>${esc(o.pressman||'No capturado')}</strong></div><div><small>Producto</small><strong>${esc(o.product||o.client)}</strong></div></div>${productionTable(productionRows([o]))}<p class="form-hint">${esc(o.notes||'Sin notas generales.')}</p>${o.status==='confirmed'?'<p class="form-hint">Cancelar devuelve el consumo descontado y conserva la trazabilidad. Los meses cerrados no admiten cancelaciones.</p>':''}`,o.status==='confirmed'?'Cancelar y devolver consumos':'',async()=>{await post('orders/cancel',{id});toast('Registro cancelado. Se devolvió el consumo descontado.');});modal.classList.add('wide-modal');modal.querySelectorAll('[data-order-detail]').forEach(el=>el.remove());}

function closeForm(){const closed=data.cuts.some(c=>c.month===month);if(closed)return;if(month>=data.today.slice(0,7)){toast('Puedes cerrar este mes cuando haya terminado. El resumen ya está disponible.');return}show('Confirmar corte mensual',monthLabel(month),'<div class="notice">Se guardará una copia definitiva de las existencias iniciales, ingresos, egresos y saldos finales de cada lote.</div><p class="form-hint">Este cierre bloquea nuevos movimientos y cancelaciones en este mes y los anteriores. Los ajustes posteriores se registran en un período abierto.</p>','Cerrar mes',async()=>{await post('cuts',{month});toast('Corte mensual guardado. Período cerrado.')})}
function exportPDF(){
 try {
  const notes=[readOnly?'Vista previa · datos del PDF original. No representa movimientos guardados en línea.':'Datos del inventario registrado.'];
  if(query)notes.push('Búsqueda: '+query);
  let title,columns,rows,summary='',sections=[];
  const col=(label,width)=>({label,width});
  if(view==='inventario'){
   const lots=visibleInventoryLots().sort((a,b)=>a.provider.localeCompare(b.provider,'es-MX')||a.code.localeCompare(b.code)||a.lot.localeCompare(b.lot));
   title=tab==='tinta'?'Inventario de tintas por proveedor':'Inventario de herramentales por proveedor';
   if(typeFilter)notes.push('Tipo: '+typeFilter);if(providerFilter)notes.push('Proveedor: '+providerFilter);if(statusFilter)notes.push('Estado: '+(statusFilter==='negative'?'Saldo negativo':statusFilter));
   notes.push('Garrafones: reparto estimado de 4,000 g más sobrante; pendiente de verificar físicamente. Los negativos se conservan para revisión.');
   columns=[col('Proveedor',78),col('Tinta / material',105),col('Código',75),col('Lote',60),col('Tipo',54),col('Existencia',56),col('Unidad',28),col('Garrafones estimados (g)',108),col('Estado / vence',77),col('Costo kg / pza MXN',65),col('Valor MXN',72)];
   rows=lots.map(l=>[l.provider,l.name,l.code,l.lot,l.kind,num(l.grams),l.category==='tinta'?'g':'pzas',l.category!=='tinta'?'-':l.grams<0?'Saldo negativo':splitContainers(l.grams).map(c=>num(c.grams)).join(' + ')||'Sin existencia',status(l)[1]+(l.category==='tinta'?' / '+new Date(Date.parse(l.entry_date)+l.shelf_days*86400000).toISOString().slice(0,10):''),money(l.cost_kg),money(l.grams*l.cost_kg/(l.category==='tinta'?1000:1))]);
   summary=`${lots.length} lotes · ${groupLots(lots).length} códigos · Total: ${num(lots.reduce((s,l)=>s+l.grams,0))} ${tab==='tinta'?'g':'pzas'} · Valor: ${money(lots.reduce((s,l)=>s+l.grams*l.cost_kg/(l.category==='tinta'?1000:1),0))} MXN`;
  }else if(view==='movimientos'){
   title='Ingresos y egresos · '+monthLabel(month);
   notes.push('Movimientos: '+({all:'Todos',in:'Ingresos',out:'Egresos',initial:'Carga inicial'}[movementTab]));
   const movements=data.movements.filter(m=>m.date.slice(0,7)===month&&(movementTab==='all'||m.type===movementTab)&&`${m.name} ${m.lot} ${m.reason}`.toLowerCase().includes(query.toLowerCase()));
   columns=[col('Fecha',65),col('Tinta / material',130),col('Código',85),col('Lote',75),col('Movimiento',70),col('Cantidad',70),col('Unidad',45),col('Motivo / referencia',238)];
   rows=movements.map(m=>[m.date,m.name,m.code,m.lot,{in:'Ingreso',out:'Egreso',initial:'Carga inicial'}[m.type],(m.type==='out'?'-':m.type==='in'?'+':'')+num(m.grams),data.lots.find(l=>l.id===m.lot_id)?.category==='herramental'?'pzas':'g',m.reason]);
   summary=movements.length+' movimientos. Incluye todos los resultados, sin límite por página.';
  }else if(view==='catalogo'){
   title='Catálogo de '+(catalogTab==='tinta'?'tintas':'herramentales');
   const products=data.products.filter(p=>p.category===catalogTab&&`${p.name} ${p.code} ${p.provider}`.toLowerCase().includes(query.toLowerCase()));
   columns=[col('Proveedor',105),col('Producto',165),col('Código',95),col('Tipo',65),col('Vida útil (días)',65),col('Recompra (g / pzas)',90),col('Máximo (g / pzas)',90),col('Costo kg / pza MXN',103)];
   rows=products.map(p=>[p.provider,p.name,p.code,p.kind,p.shelf_days??365,num(p.minimum),num(p.maximum||0),money(p.cost_kg||0)]);summary=products.length+' productos. Las cantidades de catálogo no representan existencias.';
  }else if(view==='preparacion'){
   title='Tiempos de preparación · '+monthLabel(month);
   const preparations=preparationRows();
   columns=[col('Fecha',60),col('Orden',85),col('NP',48),col('Inicio',45),col('Fin',53),col('Tiempo (min)',55),col('Fecha solicitada',65),col('Hora solicitada',55),col('Insumos / herramental preparado',125),col('Producto',85),col('Observaciones',102)];
   rows=preparations.map(p=>[p.date,p.folio,p.np,p.start_time,p.end_time+(p.end_next_day?' (+1 día)':''),num(p.minutes),p.requested_date||'-',p.requested_time||'-',p.supplies,p.product,p.notes||'-']);
   summary=preparations.length+' preparaciones · Tiempo total: '+num(preparations.reduce((s,p)=>s+Number(p.minutes),0))+' min';
   notes.push('Tiempo de preparación = fin - inicio; se indica si terminó al día siguiente. No modifica las existencias.');
  }else if(view==='ordenes'){
   title='Bitácora de producción · '+monthLabel(month);
   const detail=filteredProductionRows();
   columns=[col('Orden',82),col('NP',55),col('Fecha',55),col('Prensista',55),col('Tinta / código',93),col('Lote',58),col('Ingreso (g)',52),col('Egreso (g)',52),col('Gramos totales',55),col('Metros',45),col('Notas',65),col('Producto',66),col('Estado',45)];
   rows=detail.map(({order:o,line:l})=>[o.folio,l.np||'-',o.date,o.pressman||'-',l.name+' / '+l.code,l.lot,weight(l.initial_grams),weight(l.final_grams),l.initial_grams!=null&&l.final_grams==null?'Pendiente':num(l.grams),l.meters??'-',l.notes||o.notes||'-',o.product||o.client,o.status==='cancelled'?'Cancelada':o.status==='draft'?'Pendiente':'Confirmada']);
   notes.push('Ingreso = peso inicial; egreso = peso final / devuelto. Consumo = inicial - final. Solo los registros confirmados descuentan inventario. Los cancelados devuelven su consumo. Los registros anteriores sin pesaje conservan su consumo histórico.');
   summary=detail.length+' renglones de producción.';
  }else{
   title='Corte mensual · '+monthLabel(month);
   const saved=data.cuts.find(c=>c.month===month),noHistory=month<data.baseline.slice(0,7);
   notes.push(saved?'Corte definitivo guardado.':'Resumen sin cierre definitivo.');
   if(noHistory)notes.push('No hay historia registrada antes de '+data.baseline+'.');
   const lots=noHistory?[]:(saved?.snapshot||monthlyRows()).filter(l=>`${l.name} ${l.code} ${l.lot}`.toLowerCase().includes(query.toLowerCase()));
   columns=[col('Tinta / material',160),col('Código',95),col('Lote',85),col('Unidad',48),col('Inicial',75),col('Ingresos',75),col('Egresos',75),col('Final',75),col('Valor final MXN',90)];
   rows=lots.map(l=>[l.name,l.code,l.lot,l.category==='tinta'?'g':'pzas',num(l.opening),num(l.incoming),num(l.outgoing),num(l.closing),money(l.closing*l.cost_kg/(l.category==='tinta'?1000:1))]);
   summary=lots.length+' lotes · Valor final: '+money(lots.reduce((s,l)=>s+l.closing*l.cost_kg/(l.category==='tinta'?1000:1),0))+' MXN';
   const detail=monthlyMovementDetails(data.movements,lots,month,lots.map(l=>l.lot_id??l.id));
   const detailColumns=[col('Fecha',64),col('Tinta / material',120),col('Código',80),col('Lote',65),col('Cantidad',65),col('Unidad',40),col('Valor MXN',75),col('Motivo / orden de producción',269)];
   sections=['in','out'].map(type=>{
    const movements=detail[type];
    const grams=movements.filter(m=>m.unit==='g').reduce((s,m)=>s+m.grams,0);
    const pieces=movements.filter(m=>m.unit==='pzas').reduce((s,m)=>s+m.grams,0);
    const total=movements.reduce((s,m)=>s+m.value,0);
    return {title:(type==='in'?'Ingresos':'Egresos')+' del mes · '+monthLabel(month),columns:detailColumns,
      rows:movements.map(m=>[m.date,m.name,m.code,m.lot,num(m.grams),m.unit,money(m.value),m.reason]),
      notes:['Detalle correspondiente a los mismos lotes y filtros del resumen. La carga inicial es saldo de apertura; las devoluciones y cancelaciones se incluyen como ingresos.'],
      emptyMessage:noHistory?'No hay historia registrada para este mes.':`No se registraron ${type==='in'?'ingresos':'egresos'} en este mes para los lotes seleccionados.`,
      summary:`${movements.length} movimientos · ${num(grams)} g · ${num(pieces)} pzas · Valor: ${money(total)} MXN`};
   });
  }
  const pdf=createTablePDF({title,subtitle:'Control de planta · Emitido el '+displayDate(data.today)+' · Moneda: MXN',notes,columns,rows,summary,sections});
  const blob=new Blob([pdf],{type:'application/pdf'}),url=URL.createObjectURL(blob),a=document.createElement('a');
  a.href=url;a.download=`reporte-${view}-${view==='inventario'||view==='catalogo'?data.today:month}.pdf`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('PDF descargado con todos los resultados de los filtros.');
 }catch(error){toast('No se pudo exportar: '+error.message)}
}
load().then(()=>{if(location.hash)go(location.hash.slice(1))}).catch(e=>{main.innerHTML=empty('No pudimos conectar con el inventario',esc(e.message));});
